const STORAGE_KEY = 'injectyou.portal.demo.v1';
const $ = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(value);
const date = value => new Date(`${value}T12:00:00`).toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' });
const future = days => { const d = new Date(); d.setDate(d.getDate() + days); return d.toISOString().slice(0,10); };
const icons = {
  grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
  compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm4 5-2.5 5.5L8 16l2.5-5.5L16 8Z',
  work:'M8 7V4h8v3M3 7h18v13H3zM3 12c5 3 13 3 18 0M10 12h4v4h-4z',
  bell:'M6 9a6 6 0 0 1 12 0v6l2 3H4l2-3V9M9 21h6',
  user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',
  arrow:'M5 12h14m-6-6 6 6-6 6', check:'m5 12 4 4L19 6',
  search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15ZM16 16l5 5',
  plus:'M12 5v14M5 12h14', close:'m6 6 12 12M6 18 18 6',
  file:'M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8M8 16h6',
  wallet:'M3 6h17v15H3V6Zm0 0V4l14-2v4M15 11h6v5h-6z',
  medal:'m8 14-2 8 6-3 6 3-2-8M18 8a6 6 0 1 1-12 0 6 6 0 0 1 12 0Z',
  clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v6l4 2',
  shield:'m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5l8-3Zm-4 9 3 3 5-5',
  logout:'M9 3H4v18h5M10 12h11m-4-4 4 4-4 4',
  download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',
  bookmark:'M6 3h12v18l-6-4-6 4V3Z',
  link:'m9 15 6-6M8 17l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 7l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',
  people:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM2 21v-2a7 7 0 0 1 14 0v2M17 3a4 4 0 0 1 0 8M19 14a6 6 0 0 1 3 5v2',
  spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z'
};
const icon = (name, cls='') => `<svg class="p-icon ${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name] || icons.grid}"/></svg>`;
const baseProjects = [
  {id:'p01',title:'Design a calmer booking experience',field:'Design',company:'Northstar Studio',fee:480,price:1800,days:21,effort:'2–3 weeks',status:'Open',color:'peach',initial:'D',summary:'Help a neighborhood studio turn a complicated booking journey into a simple, welcoming experience.',deliverables:['A clear map of the current booking journey','Three responsive screen concepts','A short design rationale and handoff notes'],capacity:2},
  {id:'p02',title:'Turn survey data into a story',field:'Data analytics',company:'Northstar Studio',fee:650,price:2250,days:9,effort:'2 weeks',status:'In progress',color:'lavender',initial:'A',summary:'Make a fictional customer survey easier to understand. Find the important patterns and present useful, well-supported recommendations.',deliverables:['A cleaned sample dataset','An accessible dashboard with three key insights','A concise recommendations document'],capacity:1},
  {id:'p03',title:'Build a thoughtful brand toolkit',field:'Design',company:'Northstar Studio',fee:520,price:1900,days:4,effort:'3 weeks',status:'Client review',color:'sage',initial:'B',summary:'Create a consistent visual toolkit for a fictional independent brand, from typography to launch assets.',deliverables:['A visual direction and brand guidelines','Six reusable social templates','Editable source files and usage notes'],capacity:1},
  {id:'p04',title:'A landing page for the community',field:'Design',company:'Northstar Studio',fee:350,price:1400,days:-7,effort:'2 weeks',status:'Completed',color:'peach',initial:'C',summary:'A warm, accessible landing page for a fictional community initiative.',deliverables:['Desktop and mobile layouts','Accessible type and color specifications','Source files and handoff notes'],capacity:1},
  {id:'p05',title:'Map a better onboarding journey',field:'Management',company:'Pine & Pattern',fee:400,price:1600,days:28,effort:'2 weeks',status:'Draft review',color:'sand',initial:'M',summary:'Turn a fragmented onboarding process into a clear, practical guide for a fictional team.',deliverables:['A process map','A reusable onboarding checklist','A short improvement proposal'],capacity:2},
  {id:'p06',title:'Make event registration effortless',field:'Design',company:'Northstar Studio',fee:450,price:1750,days:6,effort:'2 weeks',status:'Platform review',color:'lavender',initial:'E',summary:'Simplify the event registration journey through clear forms and accessible interaction design.',deliverables:['Registration flow','Responsive form screens','Interaction notes'],capacity:1}
];
const freshState = () => ({version:1, interests:['Design','Data analytics'], applications:[], saved:[], projects:baseProjects.map(p=>({...p,deadline:future(p.days)})), submissions:{p02:{status:'Draft',url:'',note:''},p03:{status:'Forwarded',url:'https://example.com/sample-brand-toolkit',note:'The revised visual direction and all six templates are ready.'},p06:{status:'Under review',url:'https://example.com/sample-registration-design',note:'The registration flow, mobile screens, and handoff notes are ready for review.'}}, assignments:{p02:'Alex Morgan',p03:'Alex Morgan',p04:'Alex Morgan',p06:'Sam Rivera'}, feedback:{}, payments:{p02:{companyPaid:true,internPaid:false},p03:{companyPaid:true,internPaid:false},p04:{companyPaid:true,internPaid:true},p06:{companyPaid:true,internPaid:false}}, certificates:{p04:{id:'IJY-DEMO-0248',status:'Valid',issued:future(-7)}}, accounts:{pine:'Pending verification',northstar:'Verified'}, activity:[]});
let memoryState;
function readState(){ try{const s=JSON.parse(localStorage.getItem(STORAGE_KEY)); if(s?.version===1 && Array.isArray(s.projects)) return s;}catch{} return memoryState || freshState(); }
function persist(s){memoryState=s;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(s));}catch{}}
const status = (value) => `<span class="p-status ${['Completed','Valid','Verified','Paid','Approved'].includes(value)?'good':['Changes requested','Revoked','Blocked'].includes(value)?'warn':['Open','In progress','Client review','Under review','Platform review'].includes(value)?'active':''}"><i></i>${$(value)}</span>`;
const button = (label, action, attrs='', type='primary') => `<button type="button" class="button button-${type} p-btn" data-action="${action}" ${attrs}>${label}</button>`;
const navs = {
  intern:[['overview','grid','Overview'],['discover','compass','Discover'],['work','work','My work'],['updates','bell','Updates'],['profile','user','Profile']],
  company:[['overview','grid','Overview'],['projects','work','Projects'],['billing','wallet','Billing'],['updates','bell','Updates']],
  admin:[['overview','grid','Overview'],['projects','work','Projects'],['submissions','file','Submissions'],['accounts','people','Accounts'],['payments','wallet','Payments'],['certificates','medal','Certificates']]
};

export function mountPortal(root, role='intern') {
  if(!['intern','company','admin'].includes(role))role='intern';
  let state=readState();
  state.companyFeedback ||= {};
  let ui={view:'overview',search:'',field:'All interests',filter:'All',modal:null,toast:'',error:''};
  let toastTimer;
  const project = id => state.projects.find(p=>p.id===id);
  const own = () => state.projects.filter(p=>state.assignments[p.id]==='Alex Morgan');
  const companyProjects = () => state.projects.filter(p=>p.company==='Northstar Studio');
  const save = (message, change) => {if(change)change();persist(state);if(message){ui.toast=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{if(root.isConnected){ui.toast='';root.querySelector('.p-toast')?.remove();}},4500);}ui.error='';render();};
  const activity = (title,detail,audience) => state.activity.unshift({title,detail,audience,time:new Date().toISOString()});
  const open = (type,id) => {ui.modal={type,id};ui.error='';render();};
  const close = () => {ui.modal=null;ui.error='';render();};
  const badge = field => `<span class="p-field">${$(field)}</span>`;
  const heading = (eyebrow,title,description,action='') => `<div class="p-page-heading"><div><span class="p-eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
  const stat = (label,value,sub,ico) => `<div class="p-stat"><div class="p-stat-top"><span>${label}</span>${icon(ico)}</div><strong>${value}</strong><small>${sub}</small></div>`;
  const empty = (title,description,action='') => `<div class="p-empty"><span>${icon('compass')}</span><h3>${title}</h3><p>${description}</p>${action}</div>`;
  const projectMark = p => `<span class="p-project-mark ${p.color||'sage'}">${p.initial||'P'}</span>`;
  const sectionTitle = (title,link='') => `<div class="p-section-title"><h2>${title}</h2>${link}</div>`;
  const viewLink = (label,view) => `<button class="p-text-button" data-view="${view}">${label} ${icon('arrow')}</button>`;
  const nextLabel = p => p.status==='Changes requested'?'Review feedback':p.status==='Client review'?'Awaiting approval':p.status==='Completed'?'View certificate':p.status==='Approved'?'Certificate pending':'Continue project';
  const personalWorkRow = p => `<button class="p-project-row" data-action="work-detail" data-id="${p.id}">${projectMark(p)}<span class="p-row-main"><strong>${$(p.title)}</strong><small>${$(p.field)} <span>·</span> Due ${date(p.deadline)}</small></span>${status(p.status)}<span class="p-row-amount">${money(p.fee)}<small>Your fee</small></span>${icon('arrow')}</button>`;
  const discoveryCard = p => `<article class="p-discovery-card"><div class="p-card-top">${projectMark(p)}<button class="p-icon-button ${state.saved.includes(p.id)?'is-saved':''}" data-action="save-project" data-id="${p.id}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${$(p.title)}" aria-pressed="${state.saved.includes(p.id)}">${icon('bookmark')}</button></div>${badge(p.field)}<h3>${$(p.title)}</h3><p>${$(p.summary)}</p><div class="p-card-meta"><span>${icon('clock')}${p.effort}</span><span>Due ${date(p.deadline)}</span></div><div class="p-card-bottom"><span><strong>${money(p.fee)}</strong><small>Your project fee</small></span>${button(state.applications.includes(p.id)?'Application sent':'View project','project-detail',`data-id="${p.id}"`,'outline')}</div></article>`;
  const discoverResults = () => {
    const list=state.projects.filter(p=>p.status==='Open' && state.interests.includes(p.field) && (ui.field==='All interests'||p.field===ui.field) && `${p.title} ${p.summary} ${p.field}`.toLowerCase().includes(ui.search.toLowerCase()) && (ui.filter!=='Saved'||state.saved.includes(p.id)));
    return `<div class="p-result-count">${list.length} ${list.length===1?'project':'projects'} for your interests</div><div class="p-project-grid">${list.map(discoveryCard).join('')}</div>${!list.length?empty('A good fit is worth finding.','Try another search or update your interests to see more projects.',viewLink('Manage interests','profile')):''}`;
  };
  function internOverview(){
    const active=own().filter(p=>!['Completed','Approved'].includes(p.status));
    const certs=Object.values(state.certificates).filter(c=>c.status==='Valid').length;
    return heading('YOUR WORKSPACE','A little progress, every day.','Welcome back, Alex. Your next chapter is taking shape.',button(`Explore projects ${icon('arrow')}`,'discover'))+
      `<div class="p-stats">${stat('Active projects',String(active.length).padStart(2,'0'),'Keep your momentum','work')}${stat('Applications',String(state.applications.length).padStart(2,'0'),'Managed by inJectyou','file')}${stat('Verified achievements',String(certs).padStart(2,'0'),'Real work, recognised','medal')}</div>
      <div class="p-overview-grid"><div><article class="p-feature"><span class="p-eyebrow">YOUR NEXT STEP</span><div class="p-feature-content"><div><h2>${active.some(p=>p.status==='Changes requested')?'Your next version starts here.':'Make your insights count.'}</h2><p>${active.some(p=>p.status==='Changes requested')?'Your coordinator has shared feedback. Review the changes and send your next version.':'Your survey project is ready for its next milestone. A clear story starts with one useful insight.'}</p>${button(`Open my work ${icon('arrow')}`,'my-work')}</div><div class="p-orbit" aria-hidden="true"><span class="p-orbit-circle one"></span><span class="p-orbit-circle two"></span><span class="p-orbit-center">${icon('spark')}</span><small>ONE STEP<br>FORWARD.</small></div></div></article>
      <section class="p-panel p-work-panel">${sectionTitle('Your active work',viewLink('View all','work'))}${active.map(personalWorkRow).join('')||empty('Room for something new','Your assigned projects will appear here.')}</section></div>
      <aside class="p-side-stack"><article class="p-panel p-journey"><div class="p-mini-icon">${icon('medal')}</div><span class="p-eyebrow">YOUR JOURNEY</span><h3>Experience you<br>can show.</h3><p>Every completed project becomes a verified part of your story.</p><div class="p-level"><span>Design · Beginner</span><strong>1 / 3</strong></div><div class="p-progress"><span style="width:33%"></span></div><small>2 more projects to your next level</small>${viewLink('View achievements','profile')}</article><article class="p-note-card">${icon('shield')}<div><strong>A person in your corner.</strong><p>Your inJectyou coordinator handles project questions and feedback.</p>${viewLink('See updates','updates')}</div></article></aside></div>`;
  }
  function discover(){return heading('FIND YOUR NEXT CHAPTER','Good work starts with curiosity.','Projects matched to your interests. No previous experience required.')+`<div class="p-search-bar"><label class="p-search">${icon('search')}<input type="search" name="project-search" placeholder="Search projects or keywords" value="${$(ui.search)}" aria-label="Search projects"/></label><label class="p-select-label"><span class="sr-only">Filter by interest</span><select name="project-field"><option>All interests</option>${state.interests.map(f=>`<option ${ui.field===f?'selected':''}>${f}</option>`).join('')}</select></label><button class="p-filter ${ui.filter==='Saved'?'selected':''}" data-action="filter-saved" aria-pressed="${ui.filter==='Saved'}">${icon('bookmark')} Saved</button></div><div class="p-discover-results">${discoverResults()}</div><div class="p-helper-line">${icon('shield')} Your fee is agreed before you start. All project communication goes through inJectyou.</div>`;}
  function work(){
    const list=own();
    const applications=state.applications.map(project).filter(p=>p&&!state.assignments[p.id]);
    if(ui.filter==='Applications')return heading('YOUR NEXT OPPORTUNITY','Applications, clearly tracked.','Your coordinator reviews each application and shares the next step.')+`<div class="p-tabs" role="group" aria-label="Project filter">${['All','Active','Applications','Completed'].map(f=>`<button type="button" data-action="work-filter" data-filter="${f}" class="${ui.filter===f?'selected':''}" aria-pressed="${ui.filter===f}">${f}</button>`).join('')}</div><section class="p-panel">${applications.map(p=>`<div class="p-project-row">${projectMark(p)}<span class="p-row-main"><strong>${$(p.title)}</strong><small>${$(p.field)} · ${money(p.fee)} your fee</small></span>${status('Application received')}${button('View project','project-detail',`data-id="${p.id}"`,'outline')}</div>`).join('')||empty('Your next application starts here.','Explore projects in your chosen fields and apply to one that interests you.',viewLink('Discover projects','discover'))}</section>`;
    return heading('MAKE IT HAPPEN','Your work, all in one place.','Clear briefs, useful feedback, and one next step at a time.')+`<div class="p-tabs" role="group" aria-label="Project filter">${['All','Active','Applications','Completed'].map(f=>`<button data-action="work-filter" data-filter="${f}" class="${ui.filter===f?'selected':''}" aria-pressed="${ui.filter===f}">${f}</button>`).join('')}</div><div class="p-work-cards">${list.filter(p=>ui.filter==='All'||(ui.filter==='Completed'?p.status==='Completed':p.status!=='Completed')).map(p=>`<article class="p-panel p-work-card"><div class="p-card-top"><div class="p-project-title">${projectMark(p)}<div>${badge(p.field)}<h2>${$(p.title)}</h2></div></div>${status(p.status)}</div><p>${$(p.summary)}</p>${state.feedback[p.id]?`<div class="p-feedback"><strong>${icon('bell')} Revision requested by your coordinator</strong><p>${$(state.feedback[p.id])}</p></div>`:''}<div class="p-work-progress"><span>Brief received</span><span>Work in progress</span><span class="${['Client review','Completed','Approved'].includes(p.status)?'done':''}">Review</span><span class="${p.status==='Completed'?'done':''}">Completed</span></div><div class="p-card-bottom"><span class="p-inline-info">${icon('clock')} Due ${date(p.deadline)} <b>·</b> ${money(p.fee)} your fee</span>${button(`${nextLabel(p)} ${icon('arrow')}`,'work-detail',`data-id="${p.id}"`)}</div></article>`).join('')}</div>${!list.length?empty('Your first project is ahead.','Apply to a project that sparks your interest. We will help with the next steps.',viewLink('Discover projects','discover')):''}`;
  }
  function profile(){
    const certEntries=Object.entries(state.certificates).filter(([id])=>state.assignments[id]==='Alex Morgan');
    return heading('A STORY BUILT THROUGH WORK','Your growing portfolio.','Your interests, achievements, and verified experience.')+`<div class="p-profile-grid"><article class="p-panel p-profile-card"><div class="p-avatar large">AM</div><h2>Alex Morgan</h2><p>Intern · Fictional preview profile</p><div class="p-divider"></div><h3>Your interests</h3><p>Choose what you would like to work on. You can change this any time.</p><form data-form="interests"><div class="p-interest-options">${['Design','Data analytics','Management','Cybersecurity','Marketing','Development'].map(f=>`<label><input type="checkbox" name="interest" value="${f}" ${state.interests.includes(f)?'checked':''}/><span>${f}</span></label>`).join('')}</div><button class="button button-primary p-btn" type="submit">Save interests</button></form></article><div><section class="p-panel">${sectionTitle('Badges & certificates')}<div class="p-achievement-grid">${certEntries.map(([id,c])=>`<article class="p-achievement ${c.status==='Revoked'?'revoked':''}"><div class="p-achievement-seal">${icon('medal')}</div>${status(c.status==='Valid'?'Verified':c.status)}<h3>${$(project(id).field)} Project Completed</h3><p>${$(project(id).title)}</p><small>Beginner · ${date(c.issued)}</small>${button('View certificate','certificate',`data-id="${id}"`,'outline')}</article>`).join('')||empty('Your experience starts here','Your first badge appears after your completed work is approved and certified.')}</div></section><section class="p-panel p-earnings">${sectionTitle('Your earnings')}<div class="p-earnings-summary"><div><span>Paid to you</span><strong>${money(own().reduce((n,p)=>n+(state.payments[p.id]?.internPaid?p.fee:0),0))}</strong></div><div><span>Awaiting payout</span><strong>${money(own().filter(p=>['Completed','Approved'].includes(p.status)&&!state.payments[p.id]?.internPaid).reduce((n,p)=>n+p.fee,0))}</strong></div></div><p class="p-muted">Payout follows approved work. Payment records in this preview are simulated.</p></section></div></div>`;
  }
  function companyOverview(){
    const list=companyProjects(), review=list.filter(p=>p.status==='Client review');
    return heading('THE COMPANY WORKSPACE','Bring your next idea to life.','Northstar Studio · Fictional preview company',button(`${icon('plus')} Start a project`,'new-project'))+`<div class="p-stats">${stat('Projects in motion',list.filter(p=>!['Completed','Approved','Open'].includes(p.status)).length,'Managed from brief to delivery','work')}${stat('Ready for your review',review.length,'Your feedback moves things forward','file')}${stat('Completed projects',list.filter(p=>p.status==='Completed').length,'Good ideas, made real','check')}</div><div class="p-overview-grid"><div><article class="p-feature company-feature"><span class="p-eyebrow">${review.length?'READY WHEN YOU ARE':'FROM IDEA TO IMPACT'}</span><div class="p-feature-content"><div><h2>${review.length?'Your next delivery<br>is ready to review.':'A better brief.<br>A stronger start.'}</h2><p>${review.length?`${$(review[0].title)} is waiting for your feedback. Review the deliverables and tell us what you think.`:'Tell us what you need. Your inJectyou coordinator will help turn it into a clear, achievable project.'}</p>${button(review.length?`Review delivery ${icon('arrow')}`:`Start a project ${icon('arrow')}`,review.length?'delivery':'new-project',review.length?`data-id="${review[0].id}"`:'')}</div><div class="p-abstract-stack" aria-hidden="true"><span></span><span></span><span>${icon('check')}</span></div></div></article><section class="p-panel">${sectionTitle('Project overview',viewLink('All projects','projects'))}${list.slice(0,4).map(companyRow).join('')}</section></div><aside class="p-side-stack"><article class="p-panel p-journey"><span class="p-eyebrow">WORKING TOGETHER</span><h3>Your idea.<br>Our coordination.</h3><ol class="p-simple-steps"><li>Share your brief</li><li>We organise the work</li><li>Review the delivery</li></ol><p>A single point of contact from the first question to the final handoff.</p>${viewLink('View updates','updates')}</article><article class="p-note-card">${icon('shield')}<div><strong>Everything in one place.</strong><p>Your brief, feedback, invoices, and delivery history stay together.</p></div></article></aside></div>`;
  }
  function companyRow(p){return `<button class="p-project-row" data-action="company-project" data-id="${p.id}">${projectMark(p)}<span class="p-row-main"><strong>${$(p.title)}</strong><small>${$(p.field)} <span>·</span> Due ${date(p.deadline)}</small></span>${status(p.status)}${icon('arrow')}</button>`;}
  function companyProjectList(){return heading('FROM BRIEF TO DELIVERY','Your projects. A clear view.','Track progress, review deliveries, and keep your feedback together.',button(`${icon('plus')} Start a project`,'new-project'))+`<div class="p-panel">${companyProjects().map(companyRow).join('')}</div><div class="p-helper-line">${icon('shield')} Your inJectyou coordinator manages all delivery and project communication.</div>`;}
  function billing(){const list=companyProjects().filter(p=>p.price>0);return heading('SIMPLE, VISIBLE RECORDS','Your project billing.','Company invoices and payment status, together. All amounts are sample USD.')+`<div class="p-stats">${stat('Total project value',money(list.reduce((n,p)=>n+p.price,0)),'Across your sample projects','work')}${stat('Recorded as paid',money(list.reduce((n,p)=>n+(state.payments[p.id]?.companyPaid?p.price:0),0)),'Payment records only','check')}${stat('Awaiting payment',money(list.reduce((n,p)=>n+(!state.payments[p.id]?.companyPaid?p.price:0),0)),'No live payment connection','wallet')}</div><section class="p-panel"><div class="p-table-wrap"><table><thead><tr><th>Invoice / project</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${list.map((p,i)=>`<tr><td><strong>${$(p.title)}</strong><small>INV-DEMO-${String(1001+i)}</small></td><td>${money(p.price)}</td><td>${status(state.payments[p.id]?.companyPaid?'Paid':'Payment pending')}</td><td>${button('View invoice','invoice',`data-id="${p.id}"`,'outline')}</td></tr>`).join('')}</tbody></table></div></section><div class="p-helper-line">${icon('shield')} This preview never collects payment information or initiates a payment.</div>`;}
  function updates(){
    const events=state.activity.filter(a=>a.audience==='all'||a.audience===role);
    const defaults=role==='intern'?[['Your brief is ready','The survey project brief and deliverables are ready in My work.'],['Your achievement is verified','Your Community landing page certificate is available in your profile.']]:[['Your brand toolkit is ready','Your coordinator has forwarded the delivery for review.'],['Payment recorded','The sample payment for the survey project has been recorded.']];
    return heading('KEEP THE CONVERSATION CLEAR','Updates from your coordinator.','Every project handoff, milestone, and piece of feedback lives here.')+`<div class="p-updates-layout"><section class="p-panel p-update-list">${[...events.map(a=>[a.title,a.detail,'Just now']),...defaults.map(a=>[...a,'Sample update'])].map((a,i)=>`<article class="p-update"><span class="p-update-icon">${icon(i===0?'bell':'check')}</span><div><small>${a[2]}</small><h3>${$(a[0])}</h3><p>${$(a[1])}</p></div></article>`).join('')}</section><aside class="p-panel p-help-card"><span class="p-mini-icon">${icon('people')}</span><h3>One helpful point of contact.</h3><p>Your coordinator keeps the brief, delivery, and feedback moving between everyone involved.</p>${button('Ask a project question','question','','outline')}<small>Demo message stays in this browser.</small></aside></div>`;
  }
  function adminOverview(){
    const submissions=state.projects.filter(p=>p.status==='Platform review');
    const draft=state.projects.filter(p=>p.status==='Draft review');
    const companyFeedback=state.projects.filter(p=>p.status==='Feedback review');
    const pending=Object.values(state.accounts).filter(v=>v==='Pending verification').length;
    return heading('OPERATIONS, WITH INTENTION','Keep good work moving.','A clear view of the decisions that need your attention.')+`<div class="p-stats four">${stat('Active projects',state.projects.filter(p=>!['Completed','Approved'].includes(p.status)).length,'Across all companies','work')}${stat('Submission reviews',submissions.length,'Ready for a quality check','file')}${stat('Account checks',pending,'Companies awaiting verification','shield')}${stat('Approved, awaiting issue',state.projects.filter(p=>p.status==='Approved').length,'Certificates to prepare','medal')}</div><div class="p-admin-grid"><section class="p-panel">${sectionTitle('Your action queue','<span class="p-quiet-tag">Priority first</span>')}${submissions.map(p=>queueRow('file','Review a submission',p.title,'review-submission',p.id,'Ready for review')).join('')}${companyFeedback.map(p=>queueRow('bell','Review company feedback',p.title,'review-company-feedback',p.id,'Coordinator handoff needed')).join('')}${draft.map(p=>queueRow('work','Review a project brief',`${p.company} · ${p.title}`,'admin-project',p.id,'Awaiting publishing')).join('')}${pending?queueRow('shield','Verify Pine & Pattern','Company onboarding · Sample record','view-accounts','','Pending verification'):''}${state.projects.filter(p=>p.status==='Approved').map(p=>queueRow('medal','Issue a project certificate',p.title,'issue-certificate',p.id,'Work approved')).join('')}${!submissions.length&&!draft.length&&!companyFeedback.length&&!pending&&!state.projects.some(p=>p.status==='Approved')?empty('The queue is clear.','All current reviews are up to date.'):''}</section><aside class="p-panel p-operating-note"><span class="p-eyebrow">THE HANDOFF</span><h3>One clear path.<br>Every project.</h3><ol class="p-simple-steps"><li>Review & publish</li><li>Assign & support</li><li>Review & forward</li><li>Approve & recognise</li></ol><div class="p-divider"></div><p>Company approval, certificate issuance, and intern payout are tracked separately.</p></aside></div><section class="p-panel">${sectionTitle('Projects at a glance',viewLink('Manage projects','projects'))}${adminProjectsTable(state.projects.slice(0,4))}</section>`;
  }
  function queueRow(ico,title,detail,action,id,tag){return `<button class="p-queue-row" data-action="${action}" data-id="${id}"><span class="p-queue-icon">${icon(ico)}</span><span class="p-row-main"><small>${tag}</small><strong>${title}</strong><p>${$(detail)}</p></span>${icon('arrow')}</button>`;}
  function adminProjectsTable(list){return `<div class="p-table-wrap"><table><thead><tr><th>Project</th><th>Company</th><th>Status</th><th>Assignment</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><strong>${$(p.title)}</strong><small>${p.field} · ${date(p.deadline)}</small></td><td>${$(p.company)}</td><td>${status(p.status)}</td><td>${$(state.assignments[p.id]||'Unassigned')}</td><td>${button('Manage','admin-project',`data-id="${p.id}"`,'outline')}</td></tr>`).join('')}</tbody></table></div>`;}
  function adminProjects(){return heading('THE FULL PROJECT PICTURE','From idea to approved work.','Review briefs, set separate fees, and keep assignments clear.')+`<section class="p-panel">${adminProjectsTable(state.projects)}</section>`;}
  function submissions(){const list=state.projects.filter(p=>state.submissions[p.id]&&state.submissions[p.id].status!=='Draft');return heading('A THOUGHTFUL QUALITY CHECK','Review before you forward.','Check work against the brief, then send a clear handoff to the company.')+`<section class="p-panel">${list.map(p=>`<div class="p-project-row">${projectMark(p)}<span class="p-row-main"><strong>${$(p.title)}</strong><small>${$(state.assignments[p.id])} · ${$(p.company)}</small></span>${status(state.submissions[p.id].status)}${button('Review submission','review-submission',`data-id="${p.id}"`,'outline')}</div>`).join('')||empty('No submissions to review','Submitted work appears here when it is ready.')}</section>`;}
  function accounts(){return heading('A STRONG START','Company verification.','Review company onboarding before enabling project activity.')+`<section class="p-panel"><div class="p-table-wrap"><table><thead><tr><th>Company</th><th>Record</th><th>Status</th><th></th></tr></thead><tbody>${[['pine','Pine & Pattern','Independent creative studio'],['northstar','Northstar Studio','Product and research studio']].map(([id,name,detail])=>`<tr><td><strong>${name}</strong><small>${detail}</small></td><td>Fictional sample company<br><small>No identity documents stored</small></td><td>${status(state.accounts[id])}</td><td>${state.accounts[id]==='Pending verification'?button('Review & verify','verify-account',`data-id="${id}"`,'outline'):state.accounts[id]==='Verified'?button('Block account','block-account',`data-id="${id}"`,'outline'):button('Restore account','restore-account',`data-id="${id}"`,'outline')}</td></tr>`).join('')}</tbody></table></div></section><div class="p-helper-line">${icon('shield')} Verification actions are simulated. This design does not collect identity documents.</div>`;}
  function payments(){const list=state.projects.filter(p=>p.price>0);return heading('SEPARATE AMOUNTS. CLEAR RECORDS.','Project payments & payouts.','Internal operations view · Sample USD · No money is transferred.')+`<div class="p-stats">${stat('Company payments recorded',money(list.reduce((n,p)=>n+(state.payments[p.id]?.companyPaid?p.price:0),0)),'Recorded company inflow','wallet')}${stat('Intern payouts recorded',money(list.reduce((n,p)=>n+(state.payments[p.id]?.internPaid?p.fee:0),0)),'Recorded intern outflow','check')}${stat('Approved payouts pending',money(list.filter(p=>['Completed','Approved'].includes(p.status)&&!state.payments[p.id]?.internPaid).reduce((n,p)=>n+p.fee,0)),'Ready for payment review','clock')}</div><section class="p-panel"><div class="p-table-wrap"><table><thead><tr><th>Project</th><th>Company price</th><th>Intern fee</th><th>Company payment</th><th>Work approval</th><th>Intern payout</th></tr></thead><tbody>${list.map(p=>`<tr><td><strong>${$(p.title)}</strong><small>${$(p.company)}</small></td><td>${money(p.price)}</td><td>${money(p.fee)}</td><td>${state.payments[p.id]?.companyPaid?status('Paid'):button('Record payment','record-company-payment',`data-id="${p.id}"`,'outline')}</td><td>${status(['Completed','Approved'].includes(p.status)?'Approved':'Pending')}</td><td>${state.payments[p.id]?.internPaid?status('Paid'):['Completed','Approved'].includes(p.status)?button('Record payout','record-payout',`data-id="${p.id}"`,'outline'):'<span class="p-muted">After approval</span>'}</td></tr>`).join('')}</tbody></table></div></section>`;}
  function certificates(){return heading('RECOGNITION WITH A RECORD','Badges & certificates.','Issue after approval. Keep a reason and history for any revocation.')+`<section class="p-panel">${sectionTitle('Ready to issue')}${state.projects.filter(p=>p.status==='Approved').map(p=>`<div class="p-project-row">${projectMark(p)}<span class="p-row-main"><strong>${$(p.title)}</strong><small>${$(state.assignments[p.id]||'Alex Morgan')} · Work approved</small></span>${button('Issue certificate','issue-certificate',`data-id="${p.id}"`)}</div>`).join('')||'<p class="p-muted p-section-note">No approved projects are awaiting a certificate.</p>'}</section><section class="p-panel">${sectionTitle('Issued certificates')}<div class="p-table-wrap"><table><thead><tr><th>Certificate</th><th>Intern / project</th><th>Status</th><th>Actions</th></tr></thead><tbody>${Object.entries(state.certificates).map(([id,c])=>`<tr><td><strong>${c.id}</strong><small>Issued ${date(c.issued)}</small></td><td><strong>${$(state.assignments[id])}</strong><small>${$(project(id)?.title)}</small></td><td>${status(c.status)}${c.reason?`<small>Reason: ${$(c.reason)}</small>`:''}</td><td><div class="p-inline-actions">${button('Preview','certificate',`data-id="${id}"`,'outline')}${button(c.status==='Revoked'?'Reissue':'Revoke',c.status==='Revoked'?'reissue-certificate':'revoke-certificate',`data-id="${id}"`,'outline')}</div></td></tr>`).join('')}</tbody></table></div></section>`;}
  const contents = {intern:{overview:internOverview,discover,work,profile,updates},company:{overview:companyOverview,projects:companyProjectList,billing,updates},admin:{overview:adminOverview,projects:adminProjects,submissions,accounts,payments,certificates}};

  function modalContent(){
    if(!ui.modal)return '';
    const {type,id}=ui.modal,p=project(id),c=state.certificates[id];
    const intro = (eyebrow,title,description='')=>`<span class="p-eyebrow">${eyebrow}</span><h2 id="p-dialog-title">${title}</h2>${description?`<p class="p-modal-description">${description}</p>`:''}`;
    const error = ui.error?`<p class="p-form-error" role="alert">${$(ui.error)}</p>`:'';
    const list = p?`<h3>What you will deliver</h3><ul class="p-deliverables">${p.deliverables.map(x=>`<li>${icon('check')}<span>${$(x)}</span></li>`).join('')}</ul>`:'';
    const facts = p?`<div class="p-modal-facts"><span>Field<strong>${p.field}</strong></span><span>Deadline<strong>${date(p.deadline)}</strong></span><span>${role==='intern'?'Your fee':'Project price'}<strong>${p.price===0&&role!=='intern'?'Quote pending':money(role==='intern'?p.fee:p.price)}</strong></span></div>`:'';
    let body='';
    if(type==='project-detail')body=intro(p.field,$(p.title),$(p.summary))+facts+list+`<div class="p-info-note">${icon('shield')} Your coordinator shares the final brief and agreed fee before you start.</div><div class="p-modal-actions">${button('Close','close-modal','','outline')}${button(state.applications.includes(id)?'Application sent':`Apply for this project ${icon('arrow')}`,'apply',`data-id="${id}" ${state.applications.includes(id)?'disabled':''}`)}</div>`;
    if(type==='work-detail'){
      if(p.status==='Completed')return certificateBody(p,c,intro);
      const sub=state.submissions[id]||{status:'Draft',url:'',note:''};
      body=intro('YOUR PROJECT BRIEF',$(p.title),$(p.summary))+status(p.status)+facts+list+(state.feedback[id]?`<div class="p-feedback"><strong>Feedback from your coordinator</strong><p>${$(state.feedback[id])}</p></div>`:'');
      if(['In progress','Changes requested'].includes(p.status))body+=`<form data-form="submit-work" data-id="${id}" class="p-form"><h3>Send your work for review</h3><label>Project or file link<input name="url" type="url" placeholder="https://example.com/your-work" value="${$(sub.url)}"/></label><span class="p-form-hint">Add a link, a sample file, or both.</span><label class="p-upload">${icon('file')}<span><strong>Choose a sample file</strong><small>Only the filename is saved. No file is uploaded.</small></span><input name="file" type="file" accept=".pdf,.zip,.png,.jpg,.docx,.csv,.xlsx" aria-label="Choose a sample submission file"/></label><label>Notes for your coordinator<textarea name="note" rows="3" maxlength="1200" placeholder="What is included? Anything you would like us to review?">${$(sub.note)}</textarea></label>${error}<div class="p-modal-actions">${button('Close','close-modal','','outline')}<button type="submit" class="button button-primary p-btn">Submit for review ${icon('arrow')}</button></div></form>`;
      else body+=`<div class="p-info-note">${icon('clock')} ${p.status==='Approved'?'Your work is approved. Your coordinator will issue the certificate and confirm your payout separately.':p.status==='Client review'?'Your work is with the company. Your coordinator will share the next update.':'Your submission is with your coordinator. You will see the next update here.'}</div><div class="p-modal-actions">${button('Done','close-modal')}</div>`;
    }
    if(type==='review-company-feedback')body=intro('COMPANY FEEDBACK','Review before passing it on.',$(p.title))+`<div class="p-feedback"><strong>Requested changes from the company</strong><p>${$(state.companyFeedback[id]||'')}</p></div><div class="p-info-note">${icon('shield')} Confirm the feedback is clear and suitable before sharing it with the assigned intern.</div><div class="p-modal-actions">${button('Close','close-modal','','outline')}${button('Share revision with intern','forward-feedback',`data-id="${id}"`)}</div>`;
    if(type==='new-project')body=intro('LET’S MAKE SOMETHING GOOD','Tell us what you have in mind.','A clear starting point is all you need. Your coordinator will help refine the details.')+`<form data-form="new-project" class="p-form"><label>Project title<input name="title" required minlength="6" maxlength="100" placeholder="e.g. Simplify our customer onboarding"/></label><label>What would a successful outcome look like?<textarea name="specification" required minlength="30" maxlength="2500" rows="4" placeholder="Describe the problem, intended audience, and what you need delivered."></textarea></label><div class="p-form-grid"><label>Field<select name="field">${['Design','Data analytics','Management','Cybersecurity','Marketing','Development'].map(f=>`<option>${f}</option>`).join('')}</select></label><label>Target deadline<input name="deadline" type="date" min="${future(1)}" required/></label></div><label>Team capacity needed<select name="capacity"><option value="1">1 project contributor</option><option value="2">2 project contributors</option><option value="3">3 project contributors</option><option value="4">4 project contributors</option></select></label><div class="p-info-note">${icon('shield')} Your coordinator will review the brief and confirm a project quote before work begins.</div>${error}<div class="p-modal-actions">${button('Cancel','close-modal','','outline')}<button type="submit" class="button button-primary p-btn">Send brief for review ${icon('arrow')}</button></div></form>`;
    if(type==='company-project')body=intro('PROJECT OVERVIEW',$(p.title),$(p.summary))+status(p.status)+facts+list+`<div class="p-project-timeline">${['Brief received','Platform review','In progress','Delivery review','Completed'].map((s,i)=>`<div class="${i<(['Draft review','Open'].includes(p.status)?2:['Completed','Approved'].includes(p.status)?5:p.status==='Client review'?4:3)?'done':''}"><span>${i+1}</span>${s}</div>`).join('')}</div>${state.companyFeedback[id]||state.feedback[id]?`<div class="p-feedback"><strong>Your requested changes</strong><p>${$(state.companyFeedback[id]||state.feedback[id])}</p></div>`:''}<div class="p-modal-actions">${button('Close','close-modal','','outline')}${p.status==='Client review'?button('Review delivery','delivery',`data-id="${id}"`):button('Ask a question','question',`data-id="${id}"`,'outline')}</div>`;
    if(type==='delivery')body=intro('READY FOR YOUR REVIEW',$(p.title),'Your coordinator has checked the delivery against your brief. Take a look and share your decision.')+`<div class="p-delivery-preview"><span>${icon('file')}</span><div><strong>Project delivery package</strong><p>Design summary · Source files · Handoff notes</p><small>Fictional preview content</small></div></div>`+list+`<div class="p-info-note">${icon('shield')} Approval confirms the work meets your brief. Any payment records remain separate.</div><div class="p-modal-actions">${button('Request changes','request-changes',`data-id="${id}"`,'outline')}${button(`${icon('check')} Approve delivery`,'confirm-approval',`data-id="${id}"`)}</div>`;
    if(type==='confirm-approval')body=intro('CONFIRM YOUR REVIEW','Ready to approve this delivery?',`You are approving “${$(p.title)}”. Your coordinator can then prepare the project’s completion record.`)+`<div class="p-info-note">${icon('check')} Demo approval only. This does not transfer money.</div><div class="p-modal-actions">${button('Back to review','delivery',`data-id="${id}"`,'outline')}${button('Approve delivery','approve-delivery',`data-id="${id}"`)}</div>`;
    if(type==='request-changes'||type==='admin-changes')body=intro('MAKE THE NEXT VERSION CLEAR','What needs to change?','Specific feedback helps the project move forward.')+`<form data-form="request-changes" data-id="${id}" class="p-form"><label>Requested changes<textarea name="feedback" rows="5" minlength="15" maxlength="1500" required placeholder="Describe what is missing or what should change, with an example if helpful."></textarea></label>${error}<div class="p-modal-actions">${button('Cancel','close-modal','','outline')}<button class="button button-primary p-btn" type="submit">Send feedback to ${role==='company'?'coordinator':'intern'}</button></div></form>`;
    if(type==='invoice')body=intro('SAMPLE INVOICE',`Project invoice · ${$(p.title)}`,'Issued to Northstar Studio · Fictional preview company')+`<div class="p-invoice-line"><span>Project services</span><strong>${money(p.price)} USD</strong></div><div class="p-invoice-line"><span>Payment status</span>${status(state.payments[id]?.companyPaid?'Paid':'Payment pending')}</div><div class="p-info-note">${icon('wallet')} This is a design preview, not a payable invoice. No payment details are collected.</div><div class="p-modal-actions">${button('Done','close-modal')}</div>`;
    if(type==='question')body=intro('YOUR COORDINATOR','What can we help with?','Keep your question attached to the project context.')+`<form data-form="question" class="p-form"><label>Project<select name="project">${(role==='intern'?own():companyProjects()).map(x=>`<option value="${x.id}" ${id===x.id?'selected':''}>${$(x.title)}</option>`).join('')}</select></label><label>Your question<textarea name="message" rows="4" required minlength="10" maxlength="1200" placeholder="Tell us where you need a little clarity."></textarea></label><small class="p-form-hint">This creates a local preview message only. Nothing is sent.</small><div class="p-modal-actions">${button('Cancel','close-modal','','outline')}<button class="button button-primary p-btn" type="submit">Save preview message</button></div></form>`;
    if(type==='admin-project')body=intro('INTERNAL PROJECT WORKSPACE',$(p.title),`${$(p.company)} · ${$(p.summary)}`)+status(p.status)+`<form data-form="project-pricing" data-id="${id}" class="p-form"><div class="p-form-grid"><label>Company project price (USD)<input name="price" type="number" min="1" step="1" value="${p.price||''}" required/></label><label>Intern project fee (USD)<input name="fee" type="number" min="1" step="1" value="${p.fee||''}" required/></label></div><p class="p-form-hint">Company price and intern fee are private to their respective workspaces.</p>${error}<button class="button button-outline p-btn" type="submit">Save amounts</button></form><div class="p-divider"></div><div class="p-modal-facts"><span>Field<strong>${p.field}</strong></span><span>Deadline<strong>${date(p.deadline)}</strong></span><span>Assigned to<strong>${$(state.assignments[id]||'Unassigned')}</strong></span></div>${list}<div class="p-modal-actions">${button('Close','close-modal','','outline')}${p.status==='Draft review'?button('Publish project','publish-project',`data-id="${id}"`):p.status==='Open'?button('Assign contributor','assign',`data-id="${id}"`):p.status==='Approved'?button('Issue certificate','issue-certificate',`data-id="${id}"`):''}</div>`;
    if(type==='assign')body=intro('A THOUGHTFUL MATCH','Assign the project.',$(p.title))+`<form data-form="assign" data-id="${id}" class="p-form"><label>Contributor<select name="intern"><option>Alex Morgan</option><option>Sam Rivera</option></select></label><div class="p-info-note">${icon('user')} Both contributors are fictional. Alex has chosen Design and Data analytics. Sam has chosen Design and Management.</div><p class="p-form-hint">${state.applications.includes(id)?'Alex Morgan has applied to this project.':'You are making a direct assignment in this demo.'}</p><div class="p-modal-actions">${button('Cancel','close-modal','','outline')}<button class="button button-primary p-btn" type="submit">Confirm assignment</button></div></form>`;
    if(type==='review-submission'){const s=state.submissions[id];body=intro('QUALITY REVIEW',$(p.title),`Submitted by ${$(state.assignments[id])} · ${$(p.company)}`)+status(s.status)+list+`<div class="p-submission-detail"><h3>Submission notes</h3><p>${$(s.note||'No additional notes.')}</p>${s.url?`<span class="p-link-preview">${icon('link')}${$(s.url)}</span>`:''}${s.file?`<span class="p-link-preview">${icon('file')}${$(s.file)} · Filename only</span>`:''}</div><div class="p-info-note">${icon('shield')} Preview links and filenames represent demo work. No submitted file content is stored.</div><div class="p-modal-actions">${button('Close','close-modal','','outline')}${p.status==='Platform review'?`${button('Request revision','admin-changes',`data-id="${id}"`,'outline')}${button('Forward to company','forward-submission',`data-id="${id}"`)}`:''}</div>`;}
    if(type==='verify-account')body=intro('COMPANY VERIFICATION','Review Pine & Pattern.','Fictional onboarding record · independent creative studio')+`<ul class="p-deliverables"><li>${icon('check')}<span>Company profile supplied</span></li><li>${icon('check')}<span>Business contact details represented by sample data</span></li><li>${icon('check')}<span>No identity documents collected in this preview</span></li></ul><div class="p-modal-actions">${button('Cancel','close-modal','','outline')}${button('Mark demo company verified','confirm-verify',`data-id="${id}"`)}</div>`;
    if(type==='block-account'||type==='revoke-certificate')body=intro('KEEP A CLEAR RECORD',type==='block-account'?'Why is this account being blocked?':'Why is this certificate being revoked?','A reason is required and will remain attached to this sample record.')+`<form data-form="reason" data-kind="${type}" data-id="${id}" class="p-form"><label>Reason<textarea name="reason" required minlength="10" maxlength="800" rows="4" placeholder="Add a clear reason for this action."></textarea></label><div class="p-info-note">${icon('shield')} This changes only the fictional record in your browser.</div><div class="p-modal-actions">${button('Cancel','close-modal','','outline')}<button class="button button-primary p-btn p-danger" type="submit">${type==='block-account'?'Block demo account':'Revoke demo certificate'}</button></div></form>`;
    if(type==='record-payout'||type==='record-company-payment')body=intro('SIMULATED PAYMENT RECORD',type==='record-payout'?'Record the intern payout?':'Record the company payment?',$(p.title))+`<div class="p-invoice-line"><span>${type==='record-payout'?'Intern payout amount':'Company payment amount'}</span><strong>${money(type==='record-payout'?p.fee:p.price)} USD</strong></div><div class="p-info-note">${icon('wallet')} This updates a demo status only. It does not charge anyone or transfer funds.</div><div class="p-modal-actions">${button('Cancel','close-modal','','outline')}${button('Record as paid','confirm-payment',`data-kind="${type}" data-id="${id}"`)}</div>`;
    if(type==='certificate')body=certificateBody(p,c,intro);
    if(type==='reset')body=intro('A FRESH LOOK','Reset the design preview?','Your sample applications, submissions, briefs, and status changes in this browser will return to the initial demo.')+`<div class="p-modal-actions">${button('Keep exploring','close-modal','','outline')}${button('Reset preview','confirm-reset')}</div>`;
    return body;
  }
  function certificateBody(p,c,intro){
    if(!c)return intro('PROJECT COMPLETION','Your certificate is being prepared.','Your coordinator issues your certificate after the work has been approved.')+`<div class="p-modal-actions">${button('Done','close-modal')}</div>`;
    return intro('VERIFIED EXPERIENCE','A milestone worth keeping.')+`<div class="p-certificate"><div class="p-cert-top"><strong>inJectyou</strong><span>SAMPLE CERTIFICATE</span></div><div class="p-cert-rule"></div><span class="p-eyebrow">CERTIFICATE OF COMPLETION</span><h3>${$(state.assignments[p.id]||'Alex Morgan')}</h3><p>has successfully completed</p><h4>${$(p.title)}</h4><p>for ${$(p.company)}, coordinated by inJectyou.</p><div class="p-cert-footer"><div><small>Issued ${date(c.issued)}</small><strong>${c.id}</strong>${status(c.status)}</div><div class="p-cert-seal">${icon('medal')}<small>DEMO<br>RECORD</small></div></div></div>${c.status==='Revoked'?`<div class="p-feedback"><strong>This certificate is revoked.</strong><p>${$(c.reason||'Contact the platform for details.')}</p></div>`:'<p class="p-form-hint">Fictional certificate. Public verification is not connected in this design preview.</p>'}<div class="p-modal-actions">${button('Close','close-modal','','outline')}${c.status==='Valid'?button(`${icon('download')} Download sample`,'download-certificate',`data-id="${p.id}"`):''}</div>`;
  }
  function downloadCertificate(id){
    const p=project(id),c=state.certificates[id];if(!c||c.status!=='Valid')return;
    const html=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sample certificate — inJectyou</title><style>body{margin:0;background:#f6f7f2;color:#172b26;font:16px/1.6 Arial,sans-serif;padding:40px}main{max-width:900px;margin:auto;padding:64px;border:1px solid #a6b9a8;background:white}header{display:flex;justify-content:space-between;border-bottom:3px solid #205c45;padding-bottom:25px}header strong{font-size:27px}small{color:#697870}section{text-align:center;padding:50px 0}h1{font-size:48px;margin:25px 0 5px}h2{font-size:26px}footer{border-top:1px solid #e1e7de;padding-top:25px;display:flex;justify-content:space-between}.notice{max-width:900px;margin:20px auto;text-align:center}@media print{body{padding:0;background:white}main{border:0}.notice{display:none}}</style><main><header><strong>inJectyou</strong><small>SAMPLE CERTIFICATE</small></header><section><small>CERTIFICATE OF COMPLETION</small><h1>${$(state.assignments[id]||'Alex Morgan')}</h1><p>has successfully completed</p><h2>${$(p.title)}</h2><p>for ${$(p.company)}, coordinated by inJectyou.</p></section><footer><span>Issued ${date(c.issued)}<br>${c.id}</span><span>Valid demo record<br>Fictional sample only</span></footer></main><p class="notice">This fictional certificate has no live verification service. Use your browser’s Print command to print or save as PDF.</p></html>`;
    const url=URL.createObjectURL(new Blob([html],{type:'text/html'}));const a=document.createElement('a');a.href=url;a.download=`inJectyou-sample-certificate-${c.id}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);save('Sample certificate downloaded. Open it and use Print to save as PDF.');
  }
  function render(){
    const title=role==='intern'?'Intern workspace':role==='company'?'Company workspace':'Admin workspace';
    const person=role==='intern'?'Alex Morgan':role==='company'?'Northstar Studio':'Operations team';
    root.innerHTML=`<div class="portal"><div class="p-preview-strip"><span><i></i> DESIGN PREVIEW <small>Fictional data · saved in this browser</small></span><span class="p-private-preview">Private design preview · sample data</span><div class="p-preview-actions"><a href="#/" data-action="exit-preview" class="p-reset">Exit workspace</a><button type="button" data-action="reset" class="p-reset">Reset preview</button></div></div><div class="p-shell"><aside class="p-sidebar"><a class="p-brand" href="#/" aria-label="inJectyou home">in<span>J</span>ectyou<span class="p-brand-dot">.</span></a><span class="p-workspace-label">${title}</span><nav class="p-nav" aria-label="${title} navigation">${navs[role].map(([view,ico,label])=>`<button data-view="${view}" class="${ui.view===view?'active':''}" ${ui.view===view?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${view==='updates'?'<i class="p-nav-dot"></i>':''}</button>`).join('')}</nav><div class="p-sidebar-bottom"><div class="p-sidebar-help"><span>GOOD WORK.<br>GREAT BEGINNINGS.</span><div class="p-sidebar-sprout" aria-hidden="true">↗</div></div><a href="#/" data-action="exit-preview">${icon('logout')} Exit workspace</a><div class="p-person"><span class="p-avatar">${role==='intern'?'AM':role==='company'?'NS':'OP'}</span><div><strong>${person}</strong><small>Preview account</small></div></div></div></aside><div class="p-main-wrap"><header class="p-topbar"><div><span>Workspace</span><b>/</b><strong>${navs[role].find(n=>n[0]===ui.view)?.[2]||'Overview'}</strong></div><span class="p-topbar-note">${icon('shield')} ${role==='admin'?'Internal operations preview':'Your next chapter starts here'}</span><button class="p-icon-button" data-view="${role==='admin'?'overview':'updates'}" aria-label="${role==='admin'?'Open action queue':'Open updates'}">${icon('bell')}<i></i></button></header><main class="p-main" id="portal-content" tabindex="-1">${(contents[role][ui.view]||contents[role].overview)()}</main><footer class="p-footer"><span>Made for the work ahead.</span><span>inJectyou · Design preview</span></footer></div></div>${ui.toast?`<div class="p-toast" role="status">${icon('check')}${$(ui.toast)}</div>`:''}${ui.modal?`<dialog class="p-dialog" aria-labelledby="p-dialog-title"><button class="p-dialog-close p-icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button><div class="p-dialog-content">${modalContent()}</div></dialog>`:''}</div>`;
    const dialog=root.querySelector('dialog');if(dialog){dialog.showModal();dialog.oncancel=e=>{e.preventDefault();close();};dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});}
  }
  root.onclick=e=>{
    const nav=e.target.closest('[data-view]');if(nav){ui.view=nav.dataset.view;ui.search='';ui.field='All interests';ui.filter='All';ui.modal=null;ui.error='';render();root.querySelector('.p-main')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'});return;}
    const el=e.target.closest('[data-action]');if(!el||el.disabled)return;
    const action=el.dataset.action,id=el.dataset.id,p=project(id);
    if(action==='exit-preview'){sessionStorage.removeItem('injectyou-preview-role');return;}
    if(action==='close-modal'){close();return;}
    if(action==='discover'||action==='my-work'||action==='view-accounts'){ui.view=action==='discover'?'discover':action==='my-work'?'work':'accounts';ui.filter='All';render();return;}
    if(action==='filter-saved'){ui.filter=ui.filter==='Saved'?'All':'Saved';render();return;}
    if(action==='work-filter'){ui.filter=el.dataset.filter;render();return;}
    if(action==='save-project'){save(state.saved.includes(id)?'Project removed from saved.':'Project saved for later.',()=>{state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];});return;}
    if(action==='apply'){if(!state.applications.includes(id)){state.applications.push(id);activity('Application received',`Your application for ${p.title} is with your coordinator.`,'intern');ui.modal=null;save('Application sent. Your coordinator will share the next step.');}return;}
    if(action==='approve-delivery'){p.status='Approved';activity('Delivery approved',`${p.title} has been approved. Your coordinator will prepare the completion record.`,'all');ui.modal=null;save('Delivery approved. Certificate issuance and payment remain separate.');return;}
    if(action==='publish-project'){const account=p.company==='Pine & Pattern'?'pine':'northstar';if(state.accounts[account]!=='Verified'){save('Verify the company account before publishing its project.');return;}if(!p.price||!p.fee){ui.error='Save a company price and intern fee before publishing.';render();return;}p.status='Open';ui.modal=null;save('Project published to interns with matching interests.');return;}
    if(action==='forward-feedback'){state.feedback[id]=state.companyFeedback[id];delete state.companyFeedback[id];p.status='Changes requested';if(state.submissions[id])state.submissions[id].status='Revision requested';activity('Feedback is ready',`Your coordinator has shared changes for ${p.title}.`,'intern');ui.modal=null;save('Revision request shared with the intern.');return;}
    if(action==='forward-submission'){p.status='Client review';state.submissions[id].status='Forwarded';activity('A delivery is ready to review',`${p.title} has been forwarded by your coordinator.`,'company');activity('Your work has moved forward',`${p.title} is now with the company for review.`,'intern');ui.modal=null;save('Submission forwarded. Company review is now available.');return;}
    if(action==='confirm-verify'){state.accounts[id]='Verified';ui.modal=null;save('Demo company marked as verified.');return;}
    if(action==='restore-account'){state.accounts[id]='Verified';save('Demo account restored.');return;}
    if(action==='confirm-payment'){state.payments[id] ||= {companyPaid:false,internPaid:false};state.payments[id][el.dataset.kind==='record-payout'?'internPaid':'companyPaid']=true;ui.modal=null;save('Demo payment record updated. No money was transferred.');return;}
    if(action==='issue-certificate'||action==='reissue-certificate'){if(action==='issue-certificate'&&p.status!=='Approved')return;p.status='Completed';const previous=state.certificates[id];state.certificates[id]={id:previous?`${previous.id.replace(/-R\d+$/,'')}-R${(previous.reissues||0)+1}`:`IJY-DEMO-${String(250+Object.keys(state.certificates).length).padStart(4,'0')}`,status:'Valid',issued:future(0),reissues:(previous?.reissues||0)+(previous?1:0)};activity('Your achievement is ready',`${p.title} now has a badge and certificate.`,'intern');ui.modal=null;save('Certificate and badge issued. Payout status is unchanged.');return;}
    if(action==='download-certificate'){downloadCertificate(id);return;}
    if(action==='confirm-reset'){state=freshState();ui={view:'overview',search:'',field:'All interests',filter:'All',modal:null,toast:'',error:''};save('Preview reset. You are ready to explore again.');return;}
    open(action,id);
  };
  root.oninput=e=>{if(e.target.name==='project-search'){ui.search=e.target.value;const region=root.querySelector('.p-discover-results');if(region)region.innerHTML=discoverResults();}};
  root.onchange=e=>{if(e.target.name==='project-field'){ui.field=e.target.value;const region=root.querySelector('.p-discover-results');if(region)region.innerHTML=discoverResults();}};
  root.onsubmit=e=>{
    const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form),type=form.dataset.form,id=form.dataset.id,p=project(id);
    if(type==='interests'){const values=data.getAll('interest');if(!values.length){save('Choose at least one interest to discover relevant projects.');return;}state.interests=values;save('Your interests are updated. Discover now reflects your choices.');return;}
    if(type==='submit-work'){const url=String(data.get('url')||'').trim(),file=data.get('file'),note=String(data.get('note')||'').trim();if(!url&&!file?.name){ui.error='Add a project link or choose a sample file before submitting.';const msg=document.createElement('p');msg.className='p-form-error';msg.setAttribute('role','alert');msg.textContent=ui.error;form.querySelector('.p-form-error')?.remove();form.querySelector('.p-modal-actions').before(msg);return;}if(url&&!/^https?:\/\//i.test(url)){ui.error='Use a link beginning with https:// or http://.';form.elements.url.setCustomValidity(ui.error);form.elements.url.reportValidity();form.elements.url.oninput=()=>form.elements.url.setCustomValidity('');return;}state.submissions[id]={url,file:file?.name||'',note,status:'Under review'};p.status='Platform review';delete state.feedback[id];activity('Submission received',`Your work for ${p.title} is with your coordinator.`,'intern');ui.modal=null;save('Work submitted for review. Your next update will appear here.');return;}
    if(type==='new-project'){const deadline=String(data.get('deadline'));if(deadline<future(1)){ui.error='Choose a deadline after today.';render();return;}const title=String(data.get('title')).trim(),summary=String(data.get('specification')).trim();if(title.length<6||summary.length<30){ui.error='Add a meaningful title and at least 30 characters describing the outcome.';render();return;}const id=`demo-${Date.now()}`;state.projects.unshift({id,title,summary,field:String(data.get('field')),deadline,capacity:Number(data.get('capacity')),fee:0,price:0,company:'Northstar Studio',status:'Draft review',color:'sage',initial:title[0].toUpperCase(),effort:'Scope to be agreed',deliverables:['Deliverables to be agreed with your coordinator']});activity('Your brief is with us',`${title} is ready for platform review. Your quote will be confirmed before work begins.`,'company');ui.modal=null;ui.view='projects';save('Brief sent for review. Your coordinator will confirm the next steps.');return;}
    if(type==='request-changes'){const feedback=String(data.get('feedback')).trim();if(feedback.length<15)return;if(role==='company'){state.companyFeedback[id]=feedback;p.status='Feedback review';activity('Feedback sent to coordinator',`Your requested changes for ${p.title} are awaiting the platform handoff.`,'company');ui.modal=null;save('Feedback sent to your coordinator for review.');return;}state.feedback[id]=feedback;p.status='Changes requested';if(state.submissions[id])state.submissions[id].status='Revision requested';activity('Feedback is ready',`Your coordinator has requested changes to ${p.title}.`,'intern');ui.modal=null;save('Feedback recorded. The project now shows a revision request.');return;}
    if(type==='question'){const target=project(data.get('project'));activity('Your preview question',`${target?.title||'Project'}: ${String(data.get('message')).trim()}`,role);ui.modal=null;ui.view='updates';save('Preview message saved locally. Nothing was sent.');return;}
    if(type==='project-pricing'){p.price=Number(data.get('price'));p.fee=Number(data.get('fee'));save('Separate company price and intern fee saved.');return;}
    if(type==='assign'){if(!state.payments[id]?.companyPaid){save('Record the company payment before assigning work.');return;}state.assignments[id]=String(data.get('intern'));state.applications=state.applications.filter(x=>x!==id);p.status='In progress';state.submissions[id]={status:'Draft',url:'',note:''};activity('Your project is ready to start',`${p.title} has been assigned. Your brief is available in My work.`,'intern');ui.modal=null;save('Contributor assigned. The project is now in progress.');return;}
    if(type==='reason'){const reason=String(data.get('reason')).trim();if(reason.length<10)return;if(form.dataset.kind==='block-account'){state.accounts[id]='Blocked';}else{state.certificates[id].status='Revoked';state.certificates[id].reason=reason;}ui.modal=null;save('Demo record updated with your reason.');return;}
  };
  render();
}
